open(d+'/lib.py','w').write('''from collections import Counter, deque


def components(grid, bg):
    """The connected (8-way) components of the non-background cells, as lists of (r, c)."""
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    seen, comps = set(), []
    for p in pts:
        if p in seen:
            continue
        q, comp = deque([p]), []
        seen.add(p)
        while q:
            r, c = q.popleft(); comp.append((r, c))
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    n = (r + dr, c + dc)
                    if 0 <= n[0] < h and 0 <= n[1] < w and n not in seen and grid[n[0]][n[1]] != bg:
                        seen.add(n); q.append(n)
        comps.append(comp)
    return comps


def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def bbox(grid, cells):
    """The subgrid of grid spanning the bounding box of the given (r, c) cells."""
    r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
    r1 = max(r for r, c in cells); c1 = max(c for r, c in cells)
    return [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]


def stamp(grid, shape, centers):
    """A copy of the grid with the shape stamped centered (its middle cell) on each center point."""
    H, W = len(shape), len(shape[0]); ar, ac = (H - 1) // 2, (W - 1) // 2
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, c in centers:
        for dr in range(H):
            for dc in range(W):
                rr, cc = r - ar + dr, c - ac + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = shape[dr][dc]
    return out


def scatter_shape(grid):
    """Every isolated single-cell object gets the largest multi-cell object stamped centered on it."""
    bg = background(grid)
    comps = components(grid, bg)
    shape_comp = max(comps, key=len)
    singles = [comp[0] for comp in comps if len(comp) == 1]
    return stamp(grid, bbox(grid, shape_comp), singles)
